function outcomes(){const c=state.client;return heading('Key outcomes','Keep every draft tied to the client’s goal.')+`<div class="page-pad"><div class="report-grid"><section class="card">${ch('star','North Star')}<div class="stack">${[['goal','North Star statement'],['audience','Who we help'],['offer','What we offer'],['cta','Next step for the audience']].map(([k,l])=>`<label class="field">${l}<textarea rows="3" data-client="${k}">${e(c[k])}</textarea></label>`).join('')}</div></section><section class="card">${ch('trend','What success looks like')}<div class="stack">${[['observations','What we have observed'],['test','What we test next'],['needs','What we need from the client']].map(([k,l])=>`<label class="field">${l}<textarea rows="3" data-client="${k}">${e(c[k])}</textarea></label>`).join('')}</div><button class="link card-footer" type="button" data-view="reports">View measured results ${arrow}</button></section></div><p class="foot-note">Changes save when you leave a field. Use verified observations; results do not prove causation.</p></div>`}
function pipeline(){return heading('Pipeline detail','A clear handoff from first draft to live content.')+`<div class="page-pad">${stageBar('')}<div class="pipeline-grid">${STAGES.map((s,i)=>{const posts=state.posts.filter(p=>stageOf(p).key===s.key);return `<section class="card pipeline-card t-${s.key}">${ch(si(s.key),`${i+1}. ${s.label}`,'','',`<span class="chip">${posts.length}</span>`)}<p class="muted-s">${s.hint}</p><div class="stack">${posts.map(bcard).join('')||'<p class="col-empty">No content at this stage.</p>'}</div></section>`}).join('')}</div></div>`}
function team(){const members=state.members||[];return heading('Team / Members','A private contact list for this workspace.')+`<div class="page-pad"><div class="report-grid"><section class="card">${ch('user','Workspace contacts','','',`<span class="chip">${members.length}</span>`)}<div class="stack">${members.map(m=>`<article class="member-row"><span class="avatar">${e(m.name.slice(0,2).toUpperCase())}</span><div><b>${e(m.name)}</b><small>${e(m.role)}</small><p>${e(m.note)}</p></div><button class="btn btn-sm" type="button" data-member-edit="${e(m.id)}">Edit</button><button class="btn btn-sm btn-danger" type="button" data-member-remove="${e(m.id)}">Remove</button></article>`).join('')||'<p class="muted-s">No contacts yet. Add the people involved in your content process.</p>'}</div><p class="foot-note">These are local records. Adding a contact does not invite anyone or grant access.</p></section><section class="card">${ch('plus','Contact details')}<form id="member-form" class="stack"><input type="hidden" name="id"><label class="field">Name<input name="name" maxlength="100" required></label><label class="field">Role<input name="role" maxlength="100" required placeholder="Client approver, writer, designer…"></label><label class="field">Notes<textarea name="note" maxlength="500" rows="3"></textarea></label><div class="btn-row"><button class="btn btn-primary" type="submit">Save contact</button><button class="btn" type="reset">Clear form</button></div></form></section></div><section class="card">${ch('circleok','Current approver')}<p>${e(state.client.approver||'No approver set.')}</p><button class="link card-footer" type="button" data-view="brief">Edit client brief ${arrow}</button></section></div>`}
function render(){const active=document.activeElement,focus=active&&main.contains&&main.contains(active)?{id:active.id,result:active.dataset?.result,key:active.dataset?.key,name:active.name,start:active.selectionStart,end:active.selectionEnd}:null;applyUI();const item=navs.find(x=>x[0]===view)||navs[0];const counts={content:state.posts.filter(p=>!['Published','Scheduled'].includes(next(p))).length,approvals:state.posts.filter(p=>stageOf(p).key==='approval').length};
 $('#nav').innerHTML=navs.filter(x=>!['outcomes','pipeline','team'].includes(x[0])).map(([key,ico,label])=>`<a href="#${key}" aria-label="${label}" class="nav-item ${view===key?'active':''}" ${view===key?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${counts[key]?`<em class="nav-count">${counts[key]}</em>`:''}</a>`).join('');
 const name=state.client.name||'Your studio';const brand=$('#brand-name'),studioBrand=$('#studio-brand-name'),profile=$('#profile-avatar');if(brand)brand.textContent=name.toUpperCase();if(studioBrand)studioBrand.textContent=name.toUpperCase();if(profile)profile.textContent=(state.client.initials||'ST').slice(0,3);if(document.body&&document.body.classList){document.body.classList.toggle('section-mode',view!=='overview')}const menu=document.querySelector('.profile-menu');if(menu)menu.open=false;const focusToggle=$('#focus-toggle');if(focusToggle){focusToggle.textContent=ui.focus?'Show full dashboard':'Focus mode';focusToggle.setAttribute&&focusToggle.setAttribute('aria-pressed',String(!!ui.focus))}$('#crumb').textContent=item[2];$('#ws-name').textContent=name;$('#ws-avatar').textContent=(state.client.initials||'ST').slice(0,3);const bd=$('#bell-dot');if(bd)bd.hidden=!counts.approvals;$('#ws-mode').textContent=state.demo?'Fictional demo':'Local workspace';$('#editor-ws').textContent=name;
 main.className='view-'+view;
 if(storageLoading){main.innerHTML='<div class="page-head"><h1>Opening your studio…</h1></div><div class="page-pad"><div class="loading-shell" role="status" aria-label="Loading saved workspace"></div></div>';return}
 main.innerHTML=(damagedStore?'<p class="storage-note">Saved data could not be read. Open Settings to export the original before replacing it.</p>':'')+(!DEMO&&storageMode!=='IndexedDB'?'<p class="storage-note" role="status">'+storageNotice()+'</p>':'')+(otherTabChanged?'<p class="warning">Another tab changed this workspace. Export this tab, then reload before editing.</p>':'')+(!storeOK?'<p class="warning">Local save is unavailable. Export a backup before closing.</p>':'')+({overview,content,calendar,approvals,brief,assets,reports,library,settings,outcomes,pipeline,team}[view]||overview)();
 if(focus){const candidates=main.querySelectorAll('input,textarea,select,button');const target=[...candidates].find(n=>focus.id?n.id===focus.id:focus.result?n.dataset.result===focus.result&&n.dataset.key===focus.key:focus.name&&n.name===focus.name);if(target){target.focus({preventScroll:true});if(typeof focus.start==='number'&&target.setSelectionRange)try{target.setSelectionRange(focus.start,focus.end)}catch(err){}}}
 if(view==='content'&&hlStage){const c=$('#col-'+hlStage);c&&c.scrollIntoView&&c.scrollIntoView({behavior:'smooth',inline:'center',block:'nearest'});hlStage=''}}
function closeNav(){const s=$('.sidebar');s&&s.classList.remove('open');const sc=$('#scrim');if(sc)sc.hidden=true}
function route(){view=location.hash.slice(1)||'overview';if(view==='studio'){view='overview';if(typeof history!=='undefined'&&history.replaceState)history.replaceState(null,'','#overview')}if(!navs.some(x=>x[0]===view))view='overview';render();closeNav();if(typeof scrollTo==='function')scrollTo(0,0)}
function openEditor(id,date){const p=state.posts.find(x=>x.id===id),f=$('#post-form');f.reset();f.elements.id.value=p?.id||'';$('#editor-title').textContent=p?`${p.id} · v${p.version}`:'New content';for(const k of ['title','channel','date','role','caption','asset','cover','stage','url'])if(p)f.elements[k].value=p[k];if(!p)f.elements.date.value=dateOK(date)?date:isoToday();f.elements.facts.checked=!!p?.facts;f.elements.rights.checked=!!p?.rights;$('#editor').showModal()}
function download(c,name,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([c],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function recovery(){if(DEMO)return true;if(otherTabChanged){toast('Reload before replacing a workspace changed in another tab.');return false}try{localStorage.setItem(KEY+'-recovery',damagedStore?localStorage.getItem(KEY):JSON.stringify(state));damagedStore=false;return true}catch(err){toast('Recovery copy failed. Export a backup before replacing data.');return false}}
function backup(){download(JSON.stringify(state,null,2),'client-studio-backup.json','application/json');toast('Backup exported.')}
const csvCell=v=>{let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};
function csv(){const keys=['id','date','channel','role','title','caption','asset','version','approval','approvedVersion','approver','evidence','stage','url'];download([keys.map(csvCell).join(','),...state.posts.map(p=>keys.map(k=>csvCell(p[k])).join(','))].join('\r\n'),'content-plan.csv','text/csv;charset=utf-8');toast('Content CSV exported.')}
function setStage(id,stage){if(!canEdit())return;const p=state.posts.find(x=>x.id===id);if(!p)return;const n=next(p);if(stage==='Scheduled'&&n!=='Ready to schedule')return toast('Only approved content can be scheduled.');if(stage==='Published'&&n!=='Scheduled')return;p.stage=stage;p.history.push({date:isoToday(),note:`Marked ${stage.toLowerCase()} (version ${p.version}).`});const saved=save();render();if(stage==='Published')openEditor(id);toast(!saved?'Changes are in memory only. Export a backup before closing.':stage==='Published'?'Marked published. Add the live URL.':'Marked scheduled.')}
function toggleFocus(){ui.focus=!ui.focus;saveUI();if(ui.focus&&view!=='overview')location.hash='overview';else render();toast(ui.focus?'Focus on. Just the next step.':'Focus off.')}
function openApproval(id){const p=state.posts.find(x=>x.id===id);if(!p||next(p)==='Review checks'||next(p)==='Complete draft')return;const f=$('#approval-form');f.reset();f.elements.id.value=p.id;f.elements.person.value=state.client.approver||'';$('#approval-context').textContent=`${p.title} · version ${p.version}`;$('#approval').showModal()}

/* Command menu */
let cmdItems=[],cmdActive=0;
function cmdSource(){const go=navs.map(([k,ico,l])=>({group:'Go to',label:l,ico,run:()=>{location.hash=k}}));const acts=[{group:'Actions',label:'New content',ico:'plus',key:'N',run:()=>openEditor()},{group:'Actions',label:ui.focus?'Exit focus mode':'Enter focus mode',ico:'focus',key:'F',run:toggleFocus},{group:'Actions',label:'Switch theme',ico:'moon',run:()=>{ui.theme=ui.theme==='dark'?'light':'dark';saveUI();render()}},{group:'Actions',label:'Export JSON backup',ico:'download',run:backup},{group:'Actions',label:'Export content CSV',ico:'download',run:csv}];const posts=state.posts.map(p=>({group:'Content',label:p.title,sub:`${p.id} · ${next(p)}`,stage:tone(p),run:()=>openEditor(p.id)}));return [...acts,...go,...posts]}
function cmdRender(){const q=($('#cmdk-q').value||'').toLowerCase().trim();cmdItems=cmdSource().filter(x=>!q||(x.label+' '+(x.sub||'')+' '+x.group).toLowerCase().includes(q));cmdActive=Math.min(cmdActive,Math.max(0,cmdItems.length-1));let last='';$('#cmdk-list').innerHTML=cmdItems.map((x,i)=>{const h=x.group!==last?`<div class="cmdk-group">${x.group}</div>`:'';last=x.group;return `${h}<button type="button" role="option" class="cmdk-item ${i===cmdActive?'on':''}" aria-selected="${i===cmdActive}" data-cmd="${i}">${x.stage?si(x.stage):icon(x.ico)}<span>${e(x.label)}</span>${x.sub?`<small>${e(x.sub)}</small>`:''}${x.key?`<kbd>${x.key}</kbd>`:''}</button>`}).join('')||'<div class="cmdk-empty">No results</div>'}
function cmdOpen(){const d=$('#cmdk');if(d.open)return;$('#cmdk-q').value='';cmdActive=0;cmdRender();d.showModal();setTimeout(()=>$('#cmdk-q').focus(),10)}
function cmdRun(i){const x=cmdItems[i];$('#cmdk').close();x&&x.run()}

