 if(ev.target&&ev.target.tagName==='DIALOG'&&ev.target.open){const r=ev.target.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)ev.target.close();return}
