$('#post-form').addEventListener('submit',ev=>{ev.preventDefault();if(!canEdit())return;const f=ev.target,v=Object.fromEntries(new FormData(f));if(!dateOK(v.date))return toast('Choose a valid date.');v.facts=f.elements.facts.checked;v.rights=f.elements.rights.checked;v.title=v.title.trim();v.caption=v.caption.trim();v.asset=v.asset.trim();if(!v.title||!v.caption||!v.asset)return toast('Add the title, caption and asset reference.');let old=state.posts.find(x=>x.id===v.id);if(old){let p=revise(old,v);if(p.version!==old.version)p.history=[...old.history,{date:isoToday(),note:`Edited to version ${p.version}; approval cleared.`}];state.posts[state.posts.indexOf(old)]=p}else{if(state.posts.length>=500)return toast('This workspace supports up to 500 posts.');v.id='P'+Date.now().toString(36);while(state.posts.some(p=>p.id===v.id))v.id+='x';state.posts.push({...v,version:1,approval:'Pending',approvedVersion:null,approver:'',evidence:'',history:[]})}f.elements.id.value=v.id;const saved=save();$('#editor').close();render();if(saved)toast('Saved.');else toast('Changes are in memory only. Export a backup before closing.')});
$('#approval-form').addEventListener('submit',ev=>{ev.preventDefault();if(!canEdit())return;const f=ev.target,v=Object.fromEntries(new FormData(f)),p=state.posts.find(x=>x.id===v.id);if(!p||['Complete draft','Review checks'].includes(next(p)))return toast('Complete the draft and review checks first.');if(!v.person.trim()||!v.evidence.trim())return toast('Add the approver and evidence.');p.approval=v.decision;p.approvedVersion=v.decision==='Approved'?p.version:null;p.approver=v.person.trim();p.evidence=v.evidence.trim();p.history.push({date:isoToday(),note:`${v.decision} for version ${p.version} by ${p.approver}. ${p.evidence}`});const saved=save();$('#approval').close();render();toast(!saved?'Decision is in memory only. Export a backup before closing.':v.decision==='Approved'?`Approved · version ${p.version}`:'Changes requested · recorded')});
main.addEventListener('submit',ev=>{if(ev.target.getAttribute('id')==='member-form'){ev.preventDefault();if(!canEdit())return;const v=Object.fromEntries(new FormData(ev.target));v.name=v.name.trim();v.role=v.role.trim();if(!v.name||!v.role)return toast('Add a name and role.');state.members||=[];const old=state.members.find(m=>m.id===v.id);if(old)Object.assign(old,v);else{if(state.members.length>=100)return toast('Maximum 100 contacts.');v.id='M'+Date.now().toString(36);while(state.members.some(m=>m.id===v.id))v.id+='x';state.members.push({...v})}ev.target.elements.id.value=v.id;const saved=save();render();toast(saved?'Contact saved.':'Contact kept in memory. Export a backup before closing.');return}if(!['brief-form','settings-form'].includes(ev.target.id))return;ev.preventDefault();if(!canEdit())return;Object.assign(state.client,Object.fromEntries(new FormData(ev.target)));const saved=save();render();toast(saved?(ev.target.id==='brief-form'?'Brief saved.':'Workspace saved.'):'Changes are in memory only. Export a backup before closing.')});
